$folders = 'src', 'tests'
foreach ($folder in $folders) {
    $readme = Join-Path $folder 'README.md'
    $markdown = Get-Content -Raw -LiteralPath $readme
    $paragraphs = ($markdown.Trim() -split '\r?\n\s*\r?\n' | Select-Object -Skip 1).Count
    $links = [regex]::Matches($markdown, '\]\(([^)]+)\)')
    $dirs = Get-ChildItem -LiteralPath $folder -Directory
    if ($paragraphs -lt 1 -or $paragraphs -gt 2 -or $links.Count -ne $dirs.Count) { throw "Unexpected structure in $readme" }
    foreach ($link in $links) {
        if (-not (Test-Path -LiteralPath (Join-Path $folder $link.Groups[1].Value) -PathType Container)) { throw "Broken link in $readme" }
    }
    foreach ($dir in $dirs) {
        if ($markdown -notmatch [regex]::Escape("]($($dir.Name)/)")) { throw "Missing directory in $readme" }
    }
    if ($markdown -match '(?m)[ \t]+\r?$') { throw "Trailing whitespace in $readme" }
    $words = [regex]::Matches([regex]::Replace($markdown, '\[([^\]]+)\]\([^)]+\)', '$1'), "\b[\w.-]+\b").Count
    if ($words -gt 120) { throw "$readme is too long" }
    Write-Output "$readme $paragraphs paragraphs, $words words, all directory links valid"
}

